CREATE OR REPLACE FUNCTION public.save_surprise_photos(_id uuid,_photos text[]) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF NOT EXISTS(SELECT 1 FROM profiles WHERE id=auth.uid() AND NOT banned AND deleted_at IS NULL) THEN RAISE EXCEPTION 'Account unavailable'; END IF; IF EXISTS(SELECT 1 FROM unnest(_photos) photo WHERE photo NOT LIKE auth.uid()::text || '/%') THEN RAISE EXCEPTION 'Invalid photo'; END IF; UPDATE surprises SET photos=_photos WHERE id=_id AND user_id=auth.uid() AND status IN('paid','delivered'); IF NOT FOUND THEN RAISE EXCEPTION 'Approved access required'; END IF; END $$; REVOKE ALL ON FUNCTION public.save_surprise_photos(uuid,text[]) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.save_surprise_photos(uuid,text[]) TO authenticated;